-- ============================================
-- 13. Data release fixture (P4a): DR-seed, frozen by the real freeze
-- ============================================

-- objects.search_text is trigger-maintained on the live site; the sampled
-- rows arrive without it, so fill it before the freeze copies the rows
-- (the browsing-mode harness searches it on both sides)
SELECT public.recompute_object_search_text();

SELECT 'DR-seed', 'freezing',
       (SELECT jsonb_agg(c) FROM (SELECT 'nirspec' AS c UNION ALL
         SELECT DISTINCT 'nircam/' || field FROM public.nircam_images WHERE deploy_status = 'published' UNION ALL
         -- every photometry catalog with a cross-match on a frozen object (P6b-2: band filters)
         SELECT DISTINCT 'photometry/' || ph.field || '/' || ph.catalog_name
         FROM public.catalog_matches ph JOIN public.objects o ON o.id = ph.object_id
         WHERE o.is_active AND o.has_published_spectrum) x),
       '11111111-1111-1111-1111-111111111111', now(), 'Seed fixture: the seeded catalog frozen as a published release.';
SELECT public.dr_freeze_job('DR-seed');
UPDATE public.dr_releases SET state = 'published', published_at = now(),
       published_by = '11111111-1111-1111-1111-111111111111' WHERE tag = 'DR-seed' AND state = 'frozen';
DO $$ BEGIN
  IF (SELECT state FROM public.dr_releases WHERE tag = 'DR-seed') <> 'published' THEN
    RAISE EXCEPTION 'seed: DR-seed freeze failed: %', (SELECT error FROM public.dr_releases WHERE tag = 'DR-seed');
  END IF;
END $$;

